/// <param name = "_nDXPOPspecificDataManagementHeader">NDXPOPspecificDataManagementHeader (opt)</param>
/// <returns>value changed</returns>
public boolean reqGroupIdChange(NDXPOPspecificDataManagementHeader _nDXPOPspecificDataManagementHeader = NDXPOPspecificDataManagementHeader::findRecId(this.NDXPOPspecificDataManagementHeader, false))
{
    return (_nDXPOPspecificDataManagementHeader.MarkedChange == NoYes::No || this.Marked)
        && (_nDXPOPspecificDataManagementHeader.ActiveReqGroupId  && this.ReqGroupIdNew != this.ReqGroupIdOrig);
}

