/// <summary>
/// PaffH 21.03.25
/// </summary>
/// <param name = "_NDXPOPspecificDataManagementHeader">NDXPOPspecificDataManagementHeader</param>
public void initFromHeaderTable(NDXPOPspecificDataManagementHeader _NDXPOPspecificDataManagementHeader)
{
    this.NDXPOPspecificDataManagementHeader = _NDXPOPspecificDataManagementHeader.RecId;
}

/// <summary>
/// PaffH 21.03.25
/// </summary>
/// <param name = "_inventTable">InventTable</param>
/// <param name = "_fillChangeableFields">boolean (true)</param>
public void initFromInventTable(InventTable _inventTable, boolean _fillChangeableFields = true)
{
    this.InventTable = _inventTable.RecId;
    if (_fillChangeableFields)
    {
        this.fillChangeableFieldsInventTable(_inventTable);
    }
}

/// <summary>
/// PaffH 21.03.25
/// </summary>
/// <param name = "_inventTable">InventTable</param>
public void fillChangeableFieldsInventTable(InventTable _inventTable)
{
    NDXPOPspecificDataManagementHeader nDXPOPspecificDataManagementHeader = NDXPOPspecificDataManagementHeader::findRecId(this.NDXPOPspecificDataManagementHeader, false);
    InventDim inventDimInventSiteId;
    inventDimInventSiteId.InventSiteId = nDXPOPspecificDataManagementHeader.InventSiteId;
    inventDimInventSiteId = InventDim::findOrCreate(inventDimInventSiteId);

    this.ReqGroupIdOrig = _inventTable.ReqGroupId;

    InventItemPurchSetup inventItemPurchSetup = InventItemPurchSetup::find(_inventTable.ItemId, inventDimInventSiteId.inventDimId);
    this.InventItemPurchSetupOverride = inventItemPurchSetup.Override;
    this.InventItemPurchSetupQtyMultiplesOrig = inventItemPurchSetup.MultipleQty;
    this.InventItemPurchSetupQtyLowestOrig = inventItemPurchSetup.LowestQty;
    this.InventItemPurchSetupQtyHighestOrig = inventItemPurchSetup.HighestQty;
    this.InventItemPurchSetupQtyStandardOrig = inventItemPurchSetup.StandardQty;

    InventItemPurchSetup inventItemPurchSetupDefault = InventItemPurchSetup::findDefault(_inventTable.ItemId);
    this.InventItemPurchSetupQtyMultiplesDefaultOrig = inventItemPurchSetupDefault.MultipleQty;
    this.InventItemPurchSetupQtyLowestDefaultOrig = inventItemPurchSetupDefault.LowestQty;
    this.InventItemPurchSetupQtyHighestDefaultOrig = inventItemPurchSetupDefault.HighestQty;
    this.InventItemPurchSetupQtyStandardDefaultOrig = inventItemPurchSetupDefault.StandardQty;

    InventItemInventSetup inventItemInventSetup = InventItemInventSetup::find(_inventTable.ItemId, inventDimInventSiteId.inventDimId);
    this.InventItemInventSetupOverride = inventItemInventSetup.Override;
    this.InventItemInventSetupQtyMultiplesOrig = inventItemInventSetup.MultipleQty;
    this.InventItemInventSetupQtyLowestOrig = inventItemInventSetup.LowestQty;
    this.InventItemInventSetupQtyHighestOrig = inventItemInventSetup.HighestQty;
    this.InventItemInventSetupQtyStandardOrig = inventItemInventSetup.StandardQty;

    InventItemInventSetup inventItemInventSetupDefault = InventItemInventSetup::findDefault(_inventTable.ItemId);
    this.InventItemInventSetupQtyMultiplesDefaultOrig = inventItemInventSetupDefault.MultipleQty;
    this.InventItemInventSetupQtyLowestDefaultOrig = inventItemInventSetupDefault.LowestQty;
    this.InventItemInventSetupQtyHighestDefaultOrig = inventItemInventSetupDefault.HighestQty;
    this.InventItemInventSetupQtyStandardDefaultOrig = inventItemInventSetupDefault.StandardQty;

    InventItemSalesSetup inventItemSalesSetup = InventItemSalesSetup::find(_inventTable.ItemId, inventDimInventSiteId.inventDimId);
    this.InventItemSalesSetupOverride = inventItemSalesSetup.Override;
    this.InventItemSalesSetupQtyMultiplesOrig = inventItemSalesSetup.MultipleQty;
    this.InventItemSalesSetupQtyLowestOrig = inventItemSalesSetup.LowestQty;
    this.InventItemSalesSetupQtyHighestOrig = inventItemSalesSetup.HighestQty;
    this.InventItemSalesSetupQtyStandardOrig = inventItemSalesSetup.StandardQty;

    InventItemSalesSetup inventItemSalesSetupDefault = InventItemSalesSetup::findDefault(_inventTable.ItemId);
    this.InventItemSalesSetupQtyMultiplesDefaultOrig = inventItemSalesSetupDefault.MultipleQty;
    this.InventItemSalesSetupQtyLowestDefaultOrig = inventItemSalesSetupDefault.LowestQty;
    this.InventItemSalesSetupQtyHighestDefaultOrig = inventItemSalesSetupDefault.HighestQty;
    this.InventItemSalesSetupQtyStandardDefaultOrig = inventItemSalesSetupDefault.StandardQty;
}

/// <summary>
/// PaffH 21.03.25
/// </summary>
/// <param name = "_nDXPOPspecificDataManagementHeader">NDXPOPspecificDataManagementHeader</param>
public static void refreshFromHeaderTable(NDXPOPspecificDataManagementHeader _nDXPOPspecificDataManagementHeader)
{
    NDXPOPspecificDataManagementLine nDXPOPspecificDataManagementLine;
    InventTable InventTable;
    ttsbegin;
    while select forupdate nDXPOPspecificDataManagementLine
        where nDXPOPspecificDataManagementLine.NDXPOPspecificDataManagementHeader == _nDXPOPspecificDataManagementHeader.RecId
        join inventTable
        where nDXPOPspecificDataManagementLine.InventTable == inventTable.RecId
    {
        nDXPOPspecificDataManagementLine.fillChangeableFieldsInventTable(inventTable);
        nDXPOPspecificDataManagementLine.update();
    }
    ttscommit;
}

/// <summary>
/// PaffH 21.03.25
/// </summary>
/// <param name = "_nDXPOPspecificDataManagementLine">NDXPOPspecificDataManagementLine</param>
/// <param name = "_forUpdate">boolean (true)</param>
/// <returns>NDXPOPspecificDataManagementLine</returns>
public static NDXPOPspecificDataManagementLine find(NDXPOPspecificDataManagementLine _nDXPOPspecificDataManagementLine, boolean _forUpdate = true)
{
    NDXPOPspecificDataManagementLine nDXPOPspecificDataManagementLine;
    nDXPOPspecificDataManagementLine.selectForUpdate(_forUpdate);
    select firstonly nDXPOPspecificDataManagementLine
        where nDXPOPspecificDataManagementLine.NDXPOPspecificDataManagementHeader == _nDXPOPspecificDataManagementLine.NDXPOPspecificDataManagementHeader
        && nDXPOPspecificDataManagementLine.InventTable == _nDXPOPspecificDataManagementLine.InventTable;
    return nDXPOPspecificDataManagementLine;
}

/// <summary>
/// PaffH 21.03.25
/// </summary>
/// <param name = "_nDXPOPspecificDataManagementLine">NDXPOPspecificDataManagementLine</param>
/// <param name = "_insert">boolean</param>
/// <returns>NDXPOPspecificDataManagementLine</returns>
public static NDXPOPspecificDataManagementLine findOrCreate(NDXPOPspecificDataManagementLine _nDXPOPspecificDataManagementLine, boolean _insert = true)
{
    NDXPOPspecificDataManagementLine nDXPOPspecificDataManagementLine = NDXPOPspecificDataManagementLine::find(_nDXPOPspecificDataManagementLine, true);
    if (nDXPOPspecificDataManagementLine.RecId == 0)
    {
        if (_insert)
        {
            _nDXPOPspecificDataManagementLine.insert();
        }
        return _nDXPOPspecificDataManagementLine;
    }
    return nDXPOPspecificDataManagementLine;
}

/// <summary>
/// PaffH 24.03.25
/// diff orig to new
/// </summary>
/// <returns>boolean</returns>
public boolean hasDiffOrigNew()
{
    return ((this.ReqGroupIdNew && this.ReqGroupIdNew != this.ReqGroupIdOrig));
}

/// <summary>
/// PaffH 28.03.25
/// </summary>
/// <param name = "_nDXPOPspecificDataManagementHeader">recid NDXPOPspecificDataManagementHeader</param>
/// <returns>NDXCounterMarked</returns>
public static NDXCounterMarked countMarked(NDXPOPspecificDataManagementHeader _nDXPOPspecificDataManagementHeader)
{
    NDXPOPspecificDataManagementLine nDXPOPspecificDataManagementLine;
    select count(RecId)
        from nDXPOPspecificDataManagementLine 
        where nDXPOPspecificDataManagementLine.NDXPOPspecificDataManagementHeader == _nDXPOPspecificDataManagementHeader.RecId
        && nDXPOPspecificDataManagementLine.Marked == NoYes::Yes;
    NDXCounterMarked nDXCounterMarked = int642int(nDXPOPspecificDataManagementLine.RecId);
    if (_nDXPOPspecificDataManagementHeader.CounterMarked != nDXCounterMarked)
    {
        ttsbegin;
        _nDXPOPspecificDataManagementHeader.CounterMarked = nDXCounterMarked;
        _nDXPOPspecificDataManagementHeader.selectForUpdate(true);
        _nDXPOPspecificDataManagementHeader.update();
        ttscommit;
        if (_nDXPOPspecificDataManagementHeader.isFormDataSource())
        {
            FormDataSource fds = _nDXPOPspecificDataManagementHeader.dataSource();
            fds.reread();
        }
    }
    return nDXCounterMarked;
}

