/// </summary>
/// <param name = "_tableSave"></param>
/// <param name = "_table"></param>
/// <returns>counter fieldchanges</returns>
protected Counter inventItemSetupChangeLog(Common _tableSave, common _table)
{
    Counter counterChangesFields = 0;
    SysDictTable dictTable = SysDictTable::newTableId(_table.TableId);

    for (int i = 1; i <= 4; i++)
    {
        FieldId fieldId1;
        switch (i)
        {
            case 1:
                fieldId1 = dictTable.fieldName2Id('MultipleQty');
                break;
            case 2:
                fieldId1 = dictTable.fieldName2Id('LowestQty');
                break;
            case 3:
                fieldId1 = dictTable.fieldName2Id('HighestQty');
                break;
            case 4:
                fieldId1 = dictTable.fieldName2Id('StandardQty');
                break;
        }
        if (_table.(fieldId1) != _tableSave.(fieldId1))
        {
            ++counterChangesFields;
        }
    }
    return counterChangesFields;
}

