/// <summary>
/// PaffH 01.04.25
/// </summary>
/// <param name = "_fieldId"></param>
public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId) 
    {
        case fieldNum(NDXPOPspecificDataManagementLine, InventTable) :
            this.initFromInventTable(InventTable::findByRecId(this.InventTable), true);
            break;
    }
}

/// <summary>
/// PaffH 14.04.25
/// </summary>
/// <returns>delete valid?</returns>
public boolean validateDelete()
{
    boolean ret;

    ret = super();

    if (ret)
    {
        if (this.Changed == NoYes::Yes)
        {
            return checkFailed(strFmt("@NDX:NDXPOPLineDeleteValidateError01", InventTable::findByRecId(this.InventTable).ItemId));
        }
    }

    return ret;
}

/// <summary>
/// PaffH 22.04.25
/// </summary>
/// <param name = "_nDXPOPspecificDataManagementLineTransfer">NDXPOPspecificDataManagementLineTransfer</param>
public void initFromNDXPOPspecificDataManagementLineTransfer(NDXPOPspecificDataManagementLineTransfer _nDXPOPspecificDataManagementLineTransfer)
{
    SysDictTable dictTable = new SysDictTable(tableNum(NDXPOPspecificDataManagementLine));
    FieldId fieldIdTransferLine;
    FieldId fieldIdLine;
    str fieldName;
    SysDictFieldGroup dictFieldGroup = new SysDictFieldGroup(tableNum(NDXPOPspecificDataManagementLineTransfer), tableFieldGroupStr(NDXPOPspecificDataManagementLineTransfer, ChangeableFields));
    for (int i = 1; i <= dictFieldGroup.numberOfFields(); i++)
    {
        fieldIdTransferLine = dictFieldGroup.field(i);
        fieldName = fieldId2Name(tableNum(NDXPOPspecificDataManagementLineTransfer), fieldIdTransferLine);
        fieldIdLine = dictTable.fieldName2Id(fieldName);
        this.(fieldIdLine) = _nDXPOPspecificDataManagementLineTransfer.(fieldIdTransferLine);
    }
}
